import bisect

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    S = data[1]

    base = 911
    mod = 10**9 + 7
    prefix_hash = [0] * (N + 1)
    power = [1] * (N + 1)

    for i in range(N):
        prefix_hash[i+1] = (prefix_hash[i] * base + ord(S[i])) % mod
        power[i+1] = (power[i] * base) % mod

    def get_hash(l, r):
        return (prefix_hash[r] - prefix_hash[l] * power[r - l]) % mod

    def check(len_val):
        if len_val == 0:
            return False
        seen = {}
        for i in range(N - len_val + 1):
            current_hash = get_hash(i, i + len_val)
            if current_hash not in seen:
                seen[current_hash] = [i]
            else:
                positions = seen[current_hash]
                target = i - len_val
                idx = bisect.bisect_right(positions, target) - 1
                if idx >= 0:
                    return True
                positions.append(i)
        return False

    low = 0
    high = N // 2
    answer = 0
    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            answer = mid
            low = mid + 1
        else:
            high = mid - 1
    print(answer)

