def main():
    import sys
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    strings = []
    for _ in range(N):
        s = input[idx]
        c = int(input[idx+1])
        strings.append((s, c))
        idx += 2

    heap = []
    heapq.heappush(heap, (0, ""))

    visited = {}

    while heap:
        cost, current = heapq.heappop(heap)
        if current in visited:
            continue
        visited[current] = cost
        if current == current[::-1]:
            print(cost)
            return
        for s, c in strings:
            new_front = current + s
            new_back = s + current
            new_cost = cost + c
            if new_front not in visited or new_cost < visited.get(new_front, float('inf')):
                heapq.heappush(heap, (new_cost, new_front))
            if new_back not in visited or new_cost < visited.get(new_back, float('inf')):
                heapq.heappush(heap, (new_cost, new_back))
    print(-1)

