from functools import lru_cache

def main():
    n, k = map(int, sys.stdin.readline().split())
    s = sys.stdin.readline().strip()

    @lru_cache(maxsize=None)
    def get_winner(m, s_mod):
        if m == 0:
            return s[s_mod]
        shift = pow(2, m-1, n)
        right_mod = (s_mod + shift) % n
        left_winner = get_winner(m-1, s_mod)
        right_winner = get_winner(m-1, right_mod)
        return match_result(left_winner, right_winner)

    def match_result(a, b):
        if a == b:
            return a
        win = {'R': 'S', 'P': 'R', 'S': 'P'}
        if win[a] == b:
            return a
        else:
            return b

