from functools import lru_cache

def main():
    N, K = map(int, sys.stdin.readline().split())
    A = list(map(int, sys.stdin.readline().split()))

    max_bit = 40  # since K can be up to 1e12, which is less than 2^40
    cnt_ones = [0] * (max_bit + 1)

    for bit in range(max_bit + 1):
        for a in A:
            if a & (1 << bit):
                cnt_ones[bit] += 1

    bits_K = [0] * (max_bit + 1)
    for i in range(max_bit + 1):
        bits_K[i] = (K >> i) & 1

    @lru_cache(maxsize=None)
    def dfs(pos, tight):
        if pos < 0:
            return 0
        max_sum = 0
        if tight:
            max_b = bits_K[pos]
        else:
            max_b = 1

        for b in [0, 1]:
            if b > max_b:
                continue
            new_tight = tight and (b == bits_K[pos])
            if b == 0:
                contrib = cnt_ones[pos] * (1 << pos)
            else:
                contrib = (N - cnt_ones[pos]) * (1 << pos)
            res = contrib + dfs(pos - 1, new_tight)
            if res > max_sum:
                max_sum = res
        return max_sum

    result = dfs(max_bit, True)
    print(result)

