def main():
    input = sys.stdin.read().split()
    ptr = 0
    N = int(input[ptr])
    ptr += 1

    A = []
    for _ in range(N):
        row = list(map(int, input[ptr:ptr + N-1]))
        ptr += N-1
        A.append(row)

    m = N * (N - 1) // 2
    adj = [[] for _ in range(m)]
    in_degree = [0] * m

    for i in range(N):
        opponents = A[i]
        for j in range(len(opponents) - 1):
            a = opponents[j]
            b = opponents[j + 1]
            u1 = min(i + 1, a)
            v1 = max(i + 1, a)
            idx1 = (u1 - 1) * N - (u1 - 1) * u1 // 2 + (v1 - u1 - 1)
            u2 = min(i + 1, b)
            v2 = max(i + 1, b)
            idx2 = (u2 - 1) * N - (u2 - 1) * u2 // 2 + (v2 - u2 - 1)
            adj[idx1].append(idx2)
            in_degree[idx2] += 1

    queue = deque()
    top_order = []
    for i in range(m):
        if in_degree[i] == 0:
            queue.append(i)

    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    if len(top_order) != m:
        print(-1)
    else:
        dp = [1] * m
        for u in top_order:
            for v in adj[u]:
                if dp[v] < dp[u] + 1:
                    dp[v] = dp[u] + 1
        print(max(dp))

