def main():
    N = int(sys.stdin.readline())
    A = []
    for _ in range(N):
        A.append(list(map(int, sys.stdin.readline().split())))

    # Convert players to 0-based
    for i in range(N):
        for j in range(N-1):
            A[i][j] -= 1  # Convert to 0-based

    pos = [{} for _ in range(N)]
    for i in range(N):
        for j in range(N-1):
            opponent = A[i][j]
            pos[i][opponent] = j + 1

    match_days = {}

    for i in range(N):
        last_day = 0
        for j in range(N-1):
            opponent = A[i][j]
            if i < opponent:
                match = (i, opponent)
            else:
                match = (opponent, i)
            if match not in match_days:
                l_i = j + 1
                l_j = pos[opponent][i]
                lower_bound = max(l_i, l_j)
                day = max(lower_bound, last_day + 1)
                match_days[match] = day
                last_day = day

    # Check if all matches are processed
    all_matches = set()
    for i in range(N):
        for j in range(N-1):
            opponent = A[i][j]
            if i < opponent:
                all_matches.add((i, opponent))
            else:
                all_matches.add((opponent, i))

    if len(match_days) != len(all_matches):
        print(-1)
        return

