MOD = 10**9 + 7

def count_zero_bits_sum(N):
    if N < 0:
        return 0
    bits = []
    while N > 0:
        bits.append(N & 1)
        N >>= 1
    bits = bits[::-1]
    from functools import lru_cache
    @lru_cache(maxsize=None)
    def dp(pos, tight, zeros):
        if pos == len(bits):
            return pow(2, zeros, MOD)
        limit = bits[pos] if tight else 1
        total = 0
        for digit in [0, 1]:
            if digit > limit:
                continue
            new_tight = tight and (digit == limit)
            new_zeros = zeros + (digit == 0)
            total = (total + dp(pos + 1, new_tight, new_zeros)) % MOD
        return total
    return dp(0, True, 0)

