            return 0
        return (count_zero_bits_sum(b) - count_zero_bits_sum(a - 1)) % MOD

    part1 = sum_range(L, X_max)

    part2 = 0
    for x in range(X_max + 1, R + 1):
        a = R - x
        if a < 0:
            continue
        zero_bits = []
        for i in range(60):
            if not (x & (1 << i)):
                zero_bits.append(1 << i)
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dfs(index, current_sum):
            if index == len(zero_bits):
                return 1 if current_sum <= a else 0
            include = dfs(index + 1, current_sum + zero_bits[index])
            exclude = dfs(index + 1, current_sum)
            return (include + exclude) % MOD
        cnt = dfs(0, 0)
        part2 = (part2 + cnt) % MOD

    total = (part1 + part2) % MOD
    print(total)

