def count_subsets(mask, t):
    bits = 60
    mask_bits = [(mask >> i) & 1 for i in range(bits)]
    t_bits = [(t >> i) & 1 for i in range(bits)]

    @lru_cache(maxsize=None)
    def dfs(pos, tight):
