import sys
from functools import lru_cache

def main():
    N = sys.stdin.readline().strip()
    K = int(sys.stdin.readline())
    digits = list(map(int, N))
    n = len(digits)

    @lru_cache(maxsize=None)
    def dp(pos, count, tight, leading_zero):
        if pos == n:
            return 1 if (count == K and not leading_zero) else 0
        limit = digits[pos] if tight else 9
        total = 0
        for d in range(0, limit + 1):
            new_tight = tight and (d == limit)
            new_leading_zero = leading_zero and (d == 0)
            if leading_zero:
                if d == 0:
                    new_count = count
                else:
                    new_count = count + 1
            else:
                new_count = count + (d != 0)
            total += dp(pos + 1, new_count, new_tight, new_leading_zero)
        return total

    result = dp(0, 0, True, True)
    print(result)

