import sys

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx += 1
    M_a = int(input[idx]); idx += 1
    M_b = int(input[idx]); idx += 1
    packages = []
    for _ in range(N):
        a_i = int(input[idx]); idx += 1
        b_i = int(input[idx]); idx += 1
        c_i = int(input[idx]); idx += 1
        packages.append((a_i, b_i, c_i))

    max_a = 400
    max_b = 400
    INF = 10**18
    dp = [[INF] * (max_b + 1) for _ in range(max_a + 1)]
    dp[0][0] = 0

    for a_i, b_i, c_i in packages:
        for a in range(max_a, -1, -1):
            for b in range(max_b, -1, -1):
                if dp[a][b] < INF:
                    new_a = a + a_i
                    new_b = b + b_i
                    if new_a <= max_a and new_b <= max_b:
                        if dp[new_a][new_b] > dp[a][b] + c_i:
                            dp[new_a][new_b] = dp[a][b] + c_i

    min_cost = INF
    for a in range(max_a + 1):
        for b in range(max_b + 1):
            if a * M_b == b * M_a and (a + b) > 0:
                if dp[a][b] < min_cost:
                    min_cost = dp[a][b]

    print(-1 if min_cost == INF else min_cost)

