import sys
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx]); idx +=1
    Ma = int(input[idx]); idx +=1
    Mb = int(input[idx]); idx +=1

    packages = []
    for _ in range(N):
        a = int(input[idx]); idx +=1
        b = int(input[idx]); idx +=1
        c = int(input[idx]); idx +=1
        packages.append( (a, b, c) )

    # Compute d_i = a_i * Mb - b_i * Ma
    d_list = [ a * Mb - b * Ma for a, b, _ in packages ]

    # Split into two halves
    mid = N // 2
    first_half = packages[:mid]
    second_half = packages[mid:]

    # Generate all subsets for first half
    def generate_subsets(packages):
        subsets = []
        n = len(packages)
        for mask in range(0, 1 << n):  # include mask 0 (empty subset)
            sum_d = 0
            sum_c = 0
            for i in range(n):
                if mask & (1 << i):
                    a, b, c = packages[i]
                    sum_d += a * Mb - b * Ma
                    sum_c += c
            subsets.append( (sum_d, sum_c) )
        return subsets

    first_subsets = generate_subsets(first_half)
    first_dict = defaultdict(lambda: float('inf'))
    for sum_d, sum_c in first_subsets:
        if sum_d not in first_dict or sum_c < first_dict[sum_d]:
            first_dict[sum_d] = sum_c

    second_subsets = generate_subsets(second_half)
    second_dict = defaultdict(lambda: float('inf'))
    for sum_d, sum_c in second_subsets:
        if sum_d not in second_dict or sum_c < second_dict[sum_d]:
            second_dict[sum_d] = sum_c

    min_cost = float('inf')
    for sum_d1 in first_dict:
        target = -sum_d1
        if target in second_dict:
            total_cost = first_dict[sum_d1] + second_dict[target]
            if sum_d1 == 0 and target == 0:
                # Check if both subsets are empty
                if first_dict[sum_d1] == 0 and second_dict[target] == 0:
                    # both are empty, invalid
                    continue
            if total_cost < min_cost:
                min_cost = total_cost

    # Check if min_cost is still infinity, which means no valid subset
    if min_cost == float('inf'):
        print(-1)
    else:
        print(min_cost)

