        return P[L-1] + 1
    elif X <= 1 + total_layers_L_minus_1 + 1 + total_layers_L_minus_1:
        return P[L-1] + 1 + count_patties(L-1, X - (total_layers_L_minus_1 + 2))
    else:
        return 2 * P[L-1] + 1

