        return

    def check_three(x, y, z):
        return (x == 'A' and y == 'G' and z == 'C') or (x == 'A' and y == 'C' and z == 'G') or (x == 'G' and y == 'A' and z == 'C')

    def is_valid_four(a, b, c, d):
        # Check after swapping 0 and 1
        if check_three(b, a, c) or check_three(a, c, d):
            return False
        # Check after swapping 1 and 2
        if check_three(a, c, b) or check_three(c, b, d):
            return False
        # Check after swapping 2 and 3
        if check_three(b, d, c) or check_three(a, b, d):
            return False
        return True

