    # Initialize for i = 3
    for a in ['A', 'C', 'G', 'T']:
        for b in ['A', 'C', 'G', 'T']:
            for c in ['A', 'C', 'G', 'T']:
                if not check_three(a, b, c):
                    dp[3][(a, b, c)] += 1

    # Iterate for i from 3 to N-1
    for i in range(3, N):
