import sys

def main():
    input = sys.stdin.read().split()
    idx = 0
    N = int(input[idx])
    idx += 1
    A = int(input[idx])
    idx += 1
    B = int(input[idx])
    idx += 1
    C = int(input[idx])
    idx += 1
    ops = input[idx:idx+N]

    result = []
    possible = True

    for i in range(N):
        current_op = ops[i]
        if i < N-1:
            next_op = ops[i+1]
            # Determine current_vars and next_vars
            if current_op == 'AB':
                current_vars = {'A', 'B'}
            elif current_op == 'AC':
                current_vars = {'A', 'C'}
            else:
                current_vars = {'B', 'C'}

            if next_op == 'AB':
                next_vars = {'A', 'B'}
            elif next_op == 'AC':
                next_vars = {'A', 'C'}
            else:
                next_vars = {'B', 'C'}

            common = current_vars & next_vars
            if common:
                # Determine preferred_var
                if current_op == 'AB':
                    if 'A' in common:
                        preferred_var = 'A'
                    else:
                        preferred_var = 'B'
                elif current_op == 'AC':
                    if 'A' in common:
                        preferred_var = 'A'
                    else:
                        preferred_var = 'C'
                else:  # BC
                    if 'B' in common:
                        preferred_var = 'B'
                    else:
                        preferred_var = 'C'

                # Check validity and choose
                if current_op == 'AB':
                    if preferred_var == 'A':
                        if B >= 1:
                            result.append('A')
                            A += 1
                            B -= 1
                        else:
                            result.append('B')
                            B += 1
                            A -= 1
                    else:  # preferred_var is B
                        if A >= 1:
                            result.append('B')
                            B += 1
                            A -= 1
                        else:
                            result.append('A')
                            A += 1
                            B -= 1
                elif current_op == 'AC':
                    if preferred_var == 'A':
                        if C >= 1:
                            result.append('A')
                            A += 1
                            C -= 1
                        else:
                            result.append('C')
                            C += 1
                            A -= 1
                    else:  # preferred_var is C
                        if A >= 1:
                            result.append('C')
                            C += 1
                            A -= 1
                        else:
                            result.append('A')
                            A += 1
                            C -= 1
                else:  # BC
                    if preferred_var == 'B':
                        if C >= 1:
                            result.append('B')
                            B += 1
                            C -= 1
                        else:
                            result.append('C')
                            C += 1
                            B -= 1
                    else:  # preferred_var is C
                        if B >= 1:
                            result.append('C')
                            C += 1
                            B -= 1
                        else:
                            result.append('B')
                            B += 1
                            C -= 1
            else:
                # Choose to increase the smaller variable
                if current_op == 'AB':
                    if A < B:
                        result.append('A')
                        A += 1
                        B -= 1
                    elif B < A:
                        result.append('B')
                        B += 1
                        A -= 1
                    else:
                        result.append('A')
                        A += 1
                        B -= 1
                elif current_op == 'AC':
                    if A < C:
                        result.append('A')
                        A += 1
                        C -= 1
                    elif C < A:
                        result.append('C')
                        C += 1
                        A -= 1
                    else:
                        result.append('A')
                        A += 1
                        C -= 1
                else:  # BC
                    if B < C:
                        result.append('B')
                        B += 1
                        C -= 1
                    elif C < B:
                        result.append('C')
                        C += 1
                        B -= 1
                    else:
                        result.append('B')
                        B += 1
                        C -= 1
        else:
            # Last operation
            if current_op == 'AB':
                if A < B:
                    result.append('A')
                    A += 1
                    B -= 1
                elif B < A:
                    result.append('B')
                    B += 1
                    A -= 1
                else:
                    result.append('A')
                    A += 1
                    B -= 1
            elif current_op == 'AC':
                if A < C:
                    result.append('A')
                    A += 1
                    C -= 1
                elif C < A:
                    result.append('C')
                    C += 1
                    A -= 1
                else:
                    result.append('A')
                    A += 1
                    C -= 1
            else:  # BC
                if B < C:
                    result.append('B')
                    B += 1
                    C -= 1
                elif C < B:
                    result.append('C')
                    C += 1
                    B -= 1
                else:
                    result.append('B')
                    B += 1
                    C -= 1

        # Check for negative values
        if A < 0 or B < 0 or C < 0:
            possible = False
            break

    if possible:
        print("Yes")
        for choice in result:
            print(choice)
    else:
        print("No")

