import bisect
from collections import defaultdict

def main():
    input = sys.stdin.read().split()
    idx = 0
    H = int(input[idx]); idx +=1
    W = int(input[idx]); idx +=1
    N = int(input[idx]); idx +=1

    painted = []
    rows_dict = defaultdict(list)
    for _ in range(N):
        a = int(input[idx]); idx +=1
        b = int(input[idx]); idx +=1
        painted.append((a, b))
        rows_dict[a].append(b)

    # Sort columns for each row
    for a in rows_dict:
        rows_dict[a].sort()

    unique_subrectangles = set()
    for a, b in painted:
        i_min = max(1, a - 2)
        i_max = min(H - 2, a)
        j_min = max(1, b - 2)
        j_max = min(W - 2, b)
        for i in range(i_min, i_max + 1):
            for j in range(j_min, j_max + 1):
                unique_subrectangles.add((i, j))

    freq = [0] * 10
    for (i, j) in unique_subrectangles:
        count = 0
        for row in [i, i+1, i+2]:
            if row not in rows_dict:
                continue
            cols = rows_dict[row]
            left = bisect.bisect_left(cols, j)
            right = bisect.bisect_right(cols, j + 2)
            count += (right - left)
        if count <= 9:
            freq[count] += 1

    total = (H - 2) * (W - 2)
    freq[0] = total - len(unique_subrectangles)

    for j in range(10):
        print(freq[j])

