def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    s = list(map(int, data[1:]))

    max_score = 0

    # Step 1: A = N-1, score 0
    max_score = max(max_score, 0)

    # Step 3 scenario
    for A in range((N-1)//2 + 1, N):
        B = 2 * A - (N-1)
        if B > 0:
            score = s[A] + s[N-1 - A]
            if score > max_score:
                max_score = score

    # Step 5 scenario
    for A in range((N-1)//3 + 1, N):
        if (N-1 - A) % 2 == 0:
            d = (N-1 - A) // 2
            e = (A + N-1) // 2
            score = s[A] + s[d] + s[e] + s[N-1 - A]
            if score > max_score:
                max_score = score

    print(max_score)

