def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    s = list(map(int, data[1:N+1]))

    max_score = 0

    # Case for m=3 steps
    for A in range((N-1)//2 + 1, N):
        B = 2 * A - (N-1)
        if B <= 0:
            continue
        if (A - B) == 0 or (A - B) == A:
            continue
        if 0 <= (A - B) <= N-1:
            score = s[A] + s[N-1 - A]
            if score > max_score:
                max_score = score

    # Case for m=5 steps
    for A in range((N-1)//3 + 1, N):
        numerator = 3 * A - (N-1)
        if numerator % 2 != 0:
            continue
        B = numerator // 2
        if B <= 0:
            continue
        pos2 = (N-1 - A) // 2
        pos3 = (A + N-1) // 2
        pos4 = N-1 - A
        if pos2 < 0 or pos2 >= N or pos3 < 0 or pos3 >= N or pos4 < 0 or pos4 >= N:
            continue
        if pos2 == 0 or pos3 == 0 or pos4 == 0:
            continue
        if pos2 == pos3 or pos2 == pos4 or pos3 == pos4:
            continue
        if A == pos2 or A == pos3 or A == pos4:
            continue
        if pos4 == N-1:
            continue
        score = s[A] + s[pos2] + s[pos3] + s[pos4]
        if score > max_score:
            max_score = score

    print(max_score)

