def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    s = list(map(int, data[1:]))

    max_score = -10**18

    for A in range(1, N):
        for B in range(1, N):
            visited = set()
            current = 0
            score = 0
            valid = True
            while True:
                if current in visited:
                    valid = False
                    break
                visited.add(current)
                # Step 1: move +A
                next_pos = current + A
                if next_pos == N-1:
                    score += s[next_pos]
                    break
                if next_pos < 0 or next_pos >= N:
                    valid = False
                    break
                if next_pos not in visited:
                    score += s[next_pos]
                    current = next_pos
                else:
                    valid = False
                    break
                # Step 2: move -B
                next_pos = current - B
                if next_pos == N-1:
                    score += s[next_pos]
                    break
                if next_pos < 0 or next_pos >= N:
                    valid = False
                    break
                if next_pos not in visited:
                    score += s[next_pos]
                    current = next_pos
