def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    H = int(input[ptr])
    ptr += 1
    W = int(input[ptr])
    ptr += 1

    c = []
    for _ in range(10):
        row = list(map(int, input[ptr:ptr+10]))
        ptr += 10
        c.append(row)

    # Build reversed graph
    adj_reversed = [[] for _ in range(10)]
    for i in range(10):
        for j in range(10):
            if i != j:
                adj_reversed[j].append((i, c[i][j]))

    # Dijkstra from node 1
    INF = float('inf')
    dist = [INF] * 10
    dist[1] = 0
    heap = []
    heapq.heappush(heap, (0, 1))

    while heap:
        current_dist, u = heapq.heappop(heap)
        if current_dist > dist[u]:
            continue
        for v, cost in adj_reversed[u]:
            if dist[v] > dist[u] + cost:
                dist[v] = dist[u] + cost
                heapq.heappush(heap, (dist[v], v))

    # Read the wall
    total = 0
    for _ in range(H):
        row = list(map(int, input[ptr:ptr+W]))
        ptr += W
        for cell in row:
            if cell != -1:
                total += dist[cell]
    print(total)

