            continue
        valid = True
        # Generate all divisors of x except x itself
        divisors = set()
        for i in range(1, int(math.isqrt(x)) + 1):
            if x % i == 0:
                if i != x:
                    divisors.add(i)
                if x // i != i and x // i != x:
                    divisors.add(x // i)
        # Check if any divisor is present in elements
        for d in divisors:
            if d in elements:
                valid = False
                break
        if valid:
            count += 1
    print(count)

