    pos = 0
    left, right = 0, N-1
    while left <= right:
        mid = (left + right) // 2
        if A[mid] >= 0:
            pos = mid
            right = mid - 1
        else:
            left = mid + 1

    # Binary search for the answer
    low = -10**18
    high = 10**18

    def count_pairs(X):
        count = 0
        for i in range(N-1):
            if A[i] == 0:
                if X >= 0:
                    count += (N - i - 1)
                continue
            if A[i] > 0:
                left_j = i + 1
                right_j = N - 1
                res_j = i
                while left_j <= right_j:
                    mid_j = (left_j + right_j) // 2
                    if A[i] * A[mid_j] <= X:
                        res_j = mid_j
                        left_j = mid_j + 1
                    else:
                        right_j = mid_j - 1
                count += res_j - i
            else:
                # A[i] < 0
                if X < 0:
                    start = max(pos, i + 1)
                    if start <= N - 1:
                        count += (N - start)
                else:
                    start = max(pos, i + 1)
                    if start <= N - 1:
                        count += (N - start)
                    if pos > i + 1:
