                            if A[mid_j] >= target:
                                res_j = mid_j
                                right_j = mid_j - 1
                            else:
                                left_j = mid_j + 1
                        count += (pos - res_j)
        return count

    while low < high:
        mid = (low + high) // 2
        cnt = count_pairs(mid)
        if cnt >= K:
