import sys

def main():
    N = int(sys.stdin.readline())
    R_points = []
    L_points = []
    U_points = []
    D_points = []
    for _ in range(N):
        x, y, d = sys.stdin.readline().split()
        x = int(x)
        y = int(y)
        if d == 'R':
            R_points.append((x, y))
        elif d == 'L':
            L_points.append((x, y))
        elif d == 'U':
            U_points.append((x, y))
        elif d == 'D':
            D_points.append((x, y))

    # Compute for x
    max_R_x = max(x for x, y in R_points) if R_points else -math.inf
    min_R_x = min(x for x, y in R_points) if R_points else math.inf
    max_L_x = max(x for x, y in L_points) if L_points else -math.inf
    min_L_x = min(x for x, y in L_points) if L_points else math.inf
    fixed_x_points = U_points + D_points
    max_fixed_x = max(x for x, y in fixed_x_points) if fixed_x_points else -math.inf
    min_fixed_x = min(x for x, y in fixed_x_points) if fixed_x_points else math.inf

    # Compute for y
    max_U_y = max(y for x, y in U_points) if U_points else -math.inf
    min_U_y = min(y for x, y in U_points) if U_points else math.inf
    max_D_y = max(y for x, y in D_points) if D_points else -math.inf
    min_D_y = min(y for x, y in D_points) if D_points else math.inf
    fixed_y_points = R_points + L_points
    max_fixed_y = max(y for x, y in fixed_y_points) if fixed_y_points else -math.inf
    min_fixed_y = min(y for x, y in fixed_y_points) if fixed_y_points else math.inf

    critical_times = set()

    # x_max critical times
    if max_R_x != -math.inf and max_L_x != -math.inf:
        t1 = (max_L_x - max_R_x) / 2
        if t1 >= 0:
            critical_times.add(t1)
    if max_R_x != -math.inf and max_fixed_x != -math.inf:
        t2 = max_fixed_x - max_R_x
        if t2 >= 0:
            critical_times.add(t2)
    if max_L_x != -math.inf and max_fixed_x != -math.inf:
        t3 = max_L_x - max_fixed_x
        if t3 >= 0:
            critical_times.add(t3)

    # x_min critical times
    if min_R_x != math.inf and min_L_x != math.inf:
        t4 = (min_L_x - min_R_x) / 2
        if t4 >= 0:
            critical_times.add(t4)
    if min_R_x != math.inf and min_fixed_x != math.inf:
        t5 = min_fixed_x - min_R_x
        if t5 >= 0:
            critical_times.add(t5)
    if min_L_x != math.inf and min_fixed_x != math.inf:
        t6 = min_L_x - min_fixed_x
        if t6 >= 0:
            critical_times.add(t6)

    # y_max critical times
    if max_U_y != -math.inf and max_D_y != -math.inf:
        t7 = (max_D_y - max_U_y) / 2
        if t7 >= 0:
            critical_times.add(t7)
    if max_U_y != -math.inf and max_fixed_y != -math.inf:
        t8 = max_fixed_y - max_U_y
        if t8 >= 0:
            critical_times.add(t8)
    if max_D_y != -math.inf and max_fixed_y != -math.inf:
        t9 = max_D_y - max_fixed_y
        if t9 >= 0:
            critical_times.add(t9)

    # y_min critical times
    if min_U_y != math.inf and min_D_y != math.inf:
        t10 = (min_D_y - min_U_y) / 2
        if t10 >= 0:
            critical_times.add(t10)
    if min_U_y != math.inf and min_fixed_y != math.inf:
        t11 = min_fixed_y - min_U_y
        if t11 >= 0:
            critical_times.add(t11)
    if min_D_y != math.inf and min_fixed_y != math.inf:
        t12 = min_D_y - min_fixed_y
        if t12 >= 0:
            critical_times.add(t12)

    critical_times.add(0.0)

    min_product = float('inf')

    for t in critical_times:
        # Compute x_range
        x_max_candidates = []
        if R_points:
            x_max_candidates.append(max_R_x + t)
        if L_points:
            x_max_candidates.append(max_L_x - t)
        if fixed_x_points:
            x_max_candidates.append(max_fixed_x)
        x_max = max(x_max_candidates)

        x_min_candidates = []
        if R_points:
            x_min_candidates.append(min_R_x + t)
        if L_points:
            x_min_candidates.append(min_L_x - t)
        if fixed_x_points:
            x_min_candidates.append(min_fixed_x)
        x_min = min(x_min_candidates)
        x_range = x_max - x_min

        # Compute y_range
        y_max_candidates = []
        if U_points:
            y_max_candidates.append(max_U_y + t)
        if D_points:
            y_max_candidates.append(max_D_y - t)
        if fixed_y_points:
            y_max_candidates.append(max_fixed_y)
        y_max = max(y_max_candidates)

        y_min_candidates = []
        if U_points:
            y_min_candidates.append(min_U_y + t)
        if D_points:
            y_min_candidates.append(min_D_y - t)
        if fixed_y_points:
            y_min_candidates.append(min_fixed_y)
        y_min = min(y_min_candidates)
        y_range = y_max - y_min

        product = x_range * y_range
        if product < min_product:
            min_product = product

    print("{0:.10f}".format(min_product))

