        dy_curr = y_max_curr - y_min_curr

        a1 = (dx_curr - dx_prev) / (t_curr - t_prev)
        b1 = dx_prev - a1 * t_prev
        a2 = (dy_curr - dy_prev) / (t_curr - t_prev)
        b2 = dy_prev - a2 * t_prev

