def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    H = int(data[0])
    W = int(data[1])
    K = int(data[2])
    x1 = int(data[3]) - 1
    y1 = int(data[4]) - 1
    x2 = int(data[5]) - 1
    y2 = int(data[6]) - 1

    grid = []
    idx = 7
    for _ in range(H):
        row = data[idx]
        grid.append(list(row))
        idx += 1

    # Directions: north, east, south, west
    dirs = [(-1, 0), (0, 1), (1, 0), (0, -1)]

    # Precompute for each cell the maximum steps in each direction
    # east_steps[i][j] = max steps to the east from (i,j)
    # similarly for west, north, south
    east_steps = [[0]*W for _ in range(H)]
    west_steps = [[0]*W for _ in range(H)]
    north_steps = [[0]*W for _ in range(H)]
    south_steps = [[0]*W for _ in range(H)]

    # Compute east_steps
    for i in range(H):
        for j in range(W-1, -1, -1):
            if grid[i][j] == '@':
                east_steps[i][j] = 0
            else:
                if j == W-1:
                    east_steps[i][j] = 0
                else:
                    east_steps[i][j] = 1 + east_steps[i][j+1]

    # Compute west_steps
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '@':
                west_steps[i][j] = 0
            else:
                if j == 0:
                    west_steps[i][j] = 0
                else:
                    west_steps[i][j] = 1 + west_steps[i][j-1]

    # Compute north_steps
    for j in range(W):
        for i in range(H-1, -1, -1):
            if grid[i][j] == '@':
                north_steps[i][j] = 0
            else:
                if i == 0:
                    north_steps[i][j] = 0
                else:
                    north_steps[i][j] = 1 + north_steps[i-1][j]

    # Compute south_steps
    for j in range(W):
        for i in range(H):
            if grid[i][j] == '@':
                south_steps[i][j] = 0
            else:
                if i == H-1:
                    south_steps[i][j] = 0
                else:
                    south_steps[i][j] = 1 + south_steps[i+1][j]

    # BFS
    from collections import deque
    visited = [[False]*W for _ in range(H)]
    q = deque()
    q.append((x1, y1, 0))
    visited[x1][y1] = True
    found = False
    answer = -1

    while q:
        x, y, steps = q.popleft()
        if x == x2 and y == y2:
            answer = steps
            found = True
            break
        # Check all four directions
        for dx, dy in dirs:
            if dx == -1:  # north
                max_steps = north_steps[x][y]
                if max_steps == 0:
                    continue
                max_possible = min(max_steps, K)
                if max_possible > 0:
                    nx = x - max_possible
                    ny = y
                    if not visited[nx][ny]:
                        visited[nx][ny] = True
                        q.append((nx, ny, steps + 1))
            elif dx == 1:  # south
                max_steps = south_steps[x][y]
                if max_steps == 0:
                    continue
                max_possible = min(max_steps, K)
                if max_possible > 0:
                    nx = x + max_possible
                    ny = y
                    if not visited[nx][ny]:
                        visited[nx][ny] = True
                        q.append((nx, ny, steps + 1))
            elif dy == 1:  # east
                max_steps = east_steps[x][y]
                if max_steps == 0:
                    continue
                max_possible = min(max_steps, K)
                if max_possible > 0:
                    nx = x
                    ny = y + max_possible
                    if not visited[nx][ny]:
                        visited[nx][ny] = True
                        q.append((nx, ny, steps + 1))
            elif dy == -1:  # west
                max_steps = west_steps[x][y]
                if max_steps == 0:
                    continue
                max_possible = min(max_steps, K)
                if max_possible > 0:
                    nx = x
                    ny = y - max_possible
                    if not visited[nx][ny]:
                        visited[nx][ny] = True
                        q.append((nx, ny, steps + 1))

    print(answer if found else -1)

