def solve():
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    A = list(map(int, data[1:N+1]))
    B = list(map(int, data[N+1:2*N+1]))

    # Check if B is the same as A
    same = True
    for i in range(N):
        if B[i] != A[i]:
            same = False
            break

    if not same:
        # Try to find a permutation
        B_perm = B.copy()
        for i in range(N):
            if B_perm[i] != A[i]:
                continue
            found = False
            for j in range(i+1, N):
                if B_perm[j] != A[i]:
                    B_perm[i], B_perm[j] = B_perm[j], B_perm[i]
                    found = True
                    break
            if not found:
