    idx += 1
    A = list(map(int, input[idx:idx+N]))
    idx += N
    B = list(map(int, input[idx:idx+N]))

    if B == A:
        if all(x == B[0] for x in B):
            print("No")
            return
        else:
            new_B = B.copy()
            # Find first element not equal to A[0]
            for i in range(N):
                if new_B[i] != A[0]:
                    new_B[0], new_B[i] = new_B[i], new_B[0]
                    break
            # Fix other positions
            for i in range(1, N):
                if new_B[i] == A[i]:
                    for j in range(i+1, N):
                        if new_B[j] != A[i]:
                            new_B[i], new_B[j] = new_B[j], new_B[i]
                            break
            # Check validity
            valid = True
            for i in range(N):
                if new_B[i] == A[i]:
                    valid = False
                    break
            if valid:
                print("Yes")
                print(' '.join(map(str, new_B)))
                return
            else:
                print("No")
                return
