def main():
    import sys
    S = sys.stdin.readline().strip()
    N = len(S)

    def is_possible(K):
        current_flip = 0
        flip_end = 0
        for i in range(N):
            if i >= flip_end:
                current_flip = 0
            current_bit = int(S[i]) ^ current_flip
            if current_bit == 1:
                if i + K - 1 >= N:
                    return False
                current_flip ^= 1
                flip_end = i + K
        return True

    low = 1
    high = N
    ans = 0
    while low <= high:
        mid = (low + high) // 2
        if is_possible(mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1
    print(ans)

