    for i in range(H):
        for j in range(W-1, -1, -1):
            if grid[i][j] == '#':
                right[i][j] = 0
            else:
                if j == W-1:
                    right[i][j] = 1
                else:
                    right[i][j] = right[i][j+1] + 1

