    for j in range(W):
        for i in range(H-1, -1, -1):
            if grid[i][j] == '#':
                down[i][j] = 0
            else:
                if i == H-1:
                    down[i][j] = 1
                else:
                    down[i][j] = down[i+1][j] + 1

